void update_keyboard_layout() {
    const uint16_t *t = kl_table(KeyboardLayout[0]);
    uint16_t mask_saved = KEYCODE_MASK;
    unsigned int i;
    for (i = 0; i < sizeof(kl_globals) / sizeof(kl_globals[0]); i++)
        *kl_globals[i] = t ? t[i] : 0;
    ISO_8859_1_A0 = t ? t[KL_ISO_8859_1_A0] : 0;
    if (!t) KEYCODE_MASK = mask_saved;
    for (i = 0; i < 96; i++) {
        keycodes_ascii[i] = M(t ? t[KL_ASCII_20 + i] : 0);
        keycodes_iso_8859_1[i] = M(t ? t[KL_ISO_8859_1_A0 + i] : 0);
    }
}
